// Demo input: pin the sample array from ../demo-data/recurring-customers.json
// HARD GATE: records without optInSource are excluded from sending and counted (TCPA).
const input = Array.isArray($json) ? $json : [$json];
const cadenceDaysBySubVertical = { 'pest-control': 90, landscaping: 30 };
const results = [];
let skippedNoOptIn = 0;
for (const customer of input) {
  const subVertical = `${customer.subVertical ?? 'other'}`.toLowerCase();
  const cadenceDays = cadenceDaysBySubVertical[subVertical];
  if (!cadenceDays) {
    results.push({ json: { ...customer, subVertical, reactivationAction: 'not-applicable', reason: `Recurring service reactivation not applicable for ${subVertical}.` } });
    continue;
  }
  const optInSource = `${customer.optInSource ?? ''}`.trim();
  if (!optInSource) {
    skippedNoOptIn += 1;
    results.push({ json: { ...customer, subVertical, reactivationAction: 'skipped-no-opt-in', reason: 'No optInSource on file. Hard gate: the workflow refuses to send without a consent record.' } });
    continue;
  }
  const lastServiceDate = new Date(customer.lastServiceDate ?? 0);
  const daysSinceService = Math.floor((Date.now() - lastServiceDate.getTime()) / 86400000);
  const due = daysSinceService >= cadenceDays;
  results.push({ json: { ...customer, subVertical, daysSinceService, cadenceDays, reactivationAction: due ? 'send-reactivation' : 'wait', reason: due ? 'Past recurring interval. Send opt-in-gated reactivation message with unsubscribe language, inside quiet hours and frequency caps.' : 'Within recurring interval. No message.' } });
}
results.push({ json: { summary: true, totalRecords: input.length, skippedNoOptIn, sendCount: results.filter((r) => r.json.reactivationAction === 'send-reactivation').length } });
return results;
